// Identity Adapter — normalize Telegram / Teams / n8n test payload to one shape
// Reference: 1-Day Playbook §Step 3 Identity Normalization Table
const body = $input.item.json.body || $input.item.json;

let channel = 'test';
let user_id = body.user_id || 'anonymous';
let user_name = body.user_name || 'Tester';
let message = body.message || body.text || '';
let department = body.department || '';

// Detect channel by payload shape
if (body.from && body.from.aadObjectId) {
  channel = 'teams';
  user_id = body.from.aadObjectId;
  user_name = body.from.name || 'Teams User';
  message = body.text || '';
} else if (body.message && body.message.from && body.message.from.id) {
  channel = 'telegram';
  user_id = String(body.message.from.id);
  user_name = `${body.message.from.first_name || ''} ${body.message.from.last_name || ''}`.trim();
  message = body.message.text || '';
}

// Generate trace_id (sortable + unique)
const now = new Date();
const ts = now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
const rand = Math.random().toString(36).slice(2, 8);
const trace_id = `bob-${ts}-${rand}`;

return {
  trace_id,
  channel,
  user_id,
  user_name,
  department,
  message,
  timestamp: now.toISOString(),
  start_ts: Date.now()
};

// Pre-AI Cache (Tier 0) — regex/keyword fast-path
// Reference: SDD §Cost Optimization Pre-AI Cache
// Day 1: skeleton only — populate FAQ_MAP from feedback_log Top 100 in Week 2+
const { message } = $input.item.json;
const lower = message.toLowerCase();

// Sample regex hints (extend with real FAQ list)
const FAQ_HINTS = [
  // { pattern: /^(วันลา|ลาพักร้อน)/i, category: 'HR', shortcut: 'hr-leave-policy' },
  // { pattern: /password\s+wifi/i, category: 'UNKNOWN', refuse: true }
];

let cache_hit = false;
let hint = null;
for (const h of FAQ_HINTS) {
  if (h.pattern.test(message)) { cache_hit = true; hint = h; break; }
}

return {
  ...$input.item.json,
  cache_hit,
  cache_hint: hint
};

// Parse OpenRouter router output + extract category
const prev = $('Pre-AI Cache').item.json;
const response = $input.item.json;

let category = 'UNKNOWN';
let confidence = 0;
let needs_clarification = false;

try {
  let text = response.choices?.[0]?.message?.content || response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const parsed = JSON.parse(text);
  category = ['HR', 'PRODUCT', 'GENERAL', 'UNKNOWN'].includes(parsed.category) ? parsed.category : 'UNKNOWN';
  confidence = Number(parsed.confidence || 0);
  needs_clarification = Boolean(parsed.needs_clarification);
} catch (e) {
  category = 'UNKNOWN';
}

return { ...prev, category, confidence, needs_clarification, router_raw: response };

// Normalize response from any branch into the contract shape
// Reference: 1-Day Playbook §4.3 Runtime Response Contract
const ctx = $('Parse Router Output').item.json;
const raw = $input.item.json;

let answer = '';
let model = '';
let fallback_used = false;
let escalatedOverride = null;

if (raw.choices) {
  answer = raw.choices?.[0]?.message?.content || '';
  model = raw.model || 'openrouter';
} else if (raw.answer) {
  answer = raw.answer;
  model = raw.model || 'fallback';
  fallback_used = Boolean(raw.fallback_used);
  escalatedOverride = typeof raw.escalated === 'boolean' ? raw.escalated : null;
} else if (raw.candidates) {
  answer = raw.candidates?.[0]?.content?.parts?.[0]?.text || '';
  model = 'legacy-gemini';
}

const latency_ms = Date.now() - ctx.start_ts;
const sources = (answer.match(/raw\/[\w/.ก-๙\- ]+/g) || []);
const escalated = escalatedOverride ?? /กรุณาติดต่อ|แนะนำให้ปรึกษา|ทีม HR|ทีม Sales|Product owner/.test(answer);

return {
  trace_id: ctx.trace_id,
  channel: ctx.channel,
  user_id: ctx.user_id,
  user_name: ctx.user_name,
  department: ctx.department,
  question: ctx.message,
  category: ctx.category,
  confidence: ctx.confidence,
  answer,
  sources,
  kb_relevance: sources.length > 0 ? 1 : 0,
  escalated,
  escalate_reason: escalated ? 'recommended owner contact' : '',
  fallback_used,
  model,
  latency_ms,
  cache_hit: ctx.cache_hit || false,
  feedback_options: ['👍 ถูกต้อง', '👎 ไม่ถูก/ไม่ครบ', '📝 ฉันรู้คำตอบที่ดีกว่า']
};
